const JUSTIFICATION_SECTION={"id":"choice-justification","title":"1.1. Обґрунтування вибору","intro":"Перш ніж переходити до теми, ідеї, конфлікту та режисерського задуму, з’ясуйте, чому саме цей проєкт має бути створений, чому він важливий зараз і чи реально втілити його у ваших умовах. Теоретичні пояснення до кожного пункту відкриваються окремо. Натисніть «Теорія до пункту».","published":true,"blocks":[{"id":"choiceHistorical","type":"textarea","title":"Історичний аспект","help":"Визначте історичний, культурний або біографічний контекст теми. Відбирайте лише те, що реально допомагає майбутній постановці.","placeholder":"Коротко опишіть історичний контекст і те, що з нього важливо для проєкту…","theory":"Історичний аспект допомагає зрозуміти, звідки походить тема або явище, як воно формувалося і який контекст важливо врахувати режисерові. Це може бути історія певної події, традиції, культурного явища, біографія конкретної постаті, особливості епохи або зміна суспільного ставлення до теми з часом.\n\nНе перетворюйте цей пункт на великий історичний реферат. Ваше завдання - відібрати тільки той фактаж, який допомагає осмислити майбутній проєкт і може стати матеріалом для режисерського рішення.\n\nГоловне питання: що з історичного контексту допомагає мені точніше зрозуміти цю тему сьогодні?"},{"id":"choiceSocial","type":"textarea","title":"Соціальний аспект","help":"Поясніть, чому ця тема важлива сучасній людині та для кого вона є актуальною.","placeholder":"У чому сучасна актуальність теми, кого вона стосується, які питання порушує…","theory":"Соціальний аспект показує, як тема пов’язана із сучасною людиною, суспільством, культурою та конкретною аудиторією. Навіть розважальний концерт, шоу чи церемонія існують у певному соціальному середовищі й відображають його цінності, настрої, суперечності та очікування.\n\nВизначте, яка сучасна проблема, потреба або явище стоїть за вашою темою; кого це стосується; чому про це варто говорити саме зараз; які думки або почуття тема може викликати в глядача.\n\nНедостатньо написати «тема актуальна». Поясніть, у чому саме полягає її актуальність і для кого вона є актуальною."},{"id":"choiceArtistic","type":"textarea","title":"Мистецький аспект","help":"Поясніть, чому цю тему варто втілювати саме як сценічний мистецько-видовищний проєкт.","placeholder":"Що саме сценічна форма дає цій темі: музика, простір, світло, пластика, відео, жива присутність…","theory":"Мистецький аспект відповідає на питання, чому тема потребує саме сценічного втілення. Подумайте, що вона набуває завдяки живій присутності виконавця, музиці, світлу, простору, пластичному рішенню, сценографії, відео, монтажу та взаємодії з аудиторією.\n\nВажливо також усвідомити, чому для задуму доречна саме обрана велика форма: концерт, шоу, вистава, вечір, церемонія, конкурс, фестиваль, свято або презентація.\n\nТема повинна мати не лише змістове значення, а й потенціал для образного та сценічного розвитку."},{"id":"choiceAuthor","type":"textarea","title":"Авторський аспект","help":"Сформулюйте, чому саме ви як режисер хочете говорити про цю тему.","placeholder":"Що вас особисто зачепило, хвилює, надихає або змушує поставити це питання…","theory":"Авторський аспект виявляє вашу особисту режисерську мотивацію. Чому саме ви хочете говорити про цю тему? Що в ній вас зачепило, здивувало, обурило, надихнуло або змусило замислитися?\n\nДжерелом може бути особистий досвід, життєве спостереження, професійний інтерес, певна подія, емоційний зв’язок із темою, бажання висловити позицію або спробувати нову сценічну форму.\n\nАвторський аспект не зобов’язує вас до надмірної особистої відвертості. Йдеться насамперед про власну художню позицію та місце цієї теми у вашому режисерському мисленні."},{"id":"choiceObjective","type":"textarea","title":"Об’єктивні чинники вибору","help":"Назвіть зовнішні умови, які роблять проєкт актуальним, потрібним або можливим незалежно від ваших особистих уподобань.","placeholder":"Сучасність, замовлення, подія, аудиторія, професійні умови, команда, технічна база…","theory":"Об’єктивні чинники - це обставини, що існують незалежно від особистих симпатій режисера, але впливають на вибір теми, форми і можливість реалізації проєкту.\n\nДо них належать чинник сучасності, тобто реальна гострота або значення проблеми; чинник замовлення, тобто конкретна подія, дата, організація або завдання; комерційний чинник, тобто глядацький попит, гастрольність чи продюсерська доцільність; професійний чинник, тобто можливість вирішити певне творче завдання або освоїти нову форму; творчий потенціал виконавців і постановочної групи; технічні та просторові можливості майданчика.\n\nПоставте собі питання: які реальні зовнішні обставини роблять цей проєкт актуальним, доцільним і можливим саме зараз?"},{"id":"choiceSubjective","type":"textarea","title":"Суб’єктивні чинники вибору","help":"Визначте особисті та професійні чинники, що мотивують саме вас до створення цього проєкту.","placeholder":"Особиста мотивація, світогляд, досвід, естетичні впливи, творчі здібності, образні асоціації…","theory":"Суб’єктивні чинники пов’язані з особистістю самого режисера. Це ваші творчі здібності, образне мислення, професійний досвід, світоглядна позиція, естетичні впливи, попередній творчий досвід і особиста мотивація.\n\nЗадум може виникнути після вистави, концерту, фільму, музичного твору, візуального образу або режисерського прийому, який вас емоційно вразив. Іноді його запускає одна асоціація, фраза, спостереження чи образ.\n\nНе всі суб’єктивні мотиви усвідомлюються одразу. Часто спершу виникає емоційний імпульс, а вже в процесі аналізу режисер розуміє, чому цей матеріал став для нього важливим."},{"id":"choiceSources","type":"textarea","title":"Джерела та імпульс задуму","help":"Зафіксуйте, що конкретно стало поштовхом до задуму і що воно запустило у вашій уяві.","placeholder":"Фільм, музика, реальна подія, розмова, історія, соціальна мережа, твір мистецтва, образ, асоціація…","theory":"Поштовхом до задуму можуть стати медіа, телебачення, преса, соціальні мережі, література, документалістика, поезія, кінематограф, музика, реальні події, суспільні процеси, розмови, життєві історії, спостереження, твори мистецтва або образно-метафоричні асоціації.\n\nВажливо не лише назвати джерело. Спробуйте зрозуміти, що саме воно запустило у вашому мисленні: питання, емоцію, образ, конфлікт, сценічну форму, бажання дослідити явище або висловити позицію."},{"id":"choiceReality","type":"textarea","title":"Чинник реальності","help":"Оцініть не бажаний, а реальний масштаб постановки: ресурси, людей, час, техніку, простір, бюджет і безпеку.","placeholder":"Що реально є у вашому розпорядженні? Чого немає? Що потрібно адаптувати, замінити або спростити?","wide":true,"theory":"Чинник реальності - обов’язкова перевірка задуму на можливість його практичного втілення. Сильна ідея ще не означає, що проєкт можна реалізувати в тому масштабі, у якому він виник у вашій уяві. Режисер повинен співвідносити художні бажання з конкретними виробничими умовами.\n\nОцініть доступний бюджет, кількість і рівень виконавців, наявність творчо-постановочної команди, майданчик, світло, звук, відео, сценічну механіку, декорації, костюми, спецефекти, логістику, час на підготовку, кількість можливих репетицій, доступність потрібних фахівців і безпекові умови. Окремо подумайте, які ресурси ви вже маєте, які реально можете отримати, а які існують лише у бажаній моделі проєкту.\n\nРозрізняйте художньо бажане і реально можливе. Якщо задум передбачає великий LED-екран, складну трансформацію сцени, десятки виконавців, піротехніку або дорогі декорації, а у ваших умовах цього немає, режисерське завдання полягає не в тому, щоб просто відмовитися від ідеї, а в тому, щоб знайти сценічний еквівалент. Подумайте, що можна замінити світлом, пластикою, проєкцією, звуком, реквізитом або іншим способом організації простору. Визначте, що можна скоротити без втрати сенсу.\n\nОбмеження не завжди послаблюють проєкт. Часто вони змушують знайти точніше, образніше й винахідливіше рішення.\n\nГоловне питання: чи можу я реально поставити цей проєкт у тих умовах, у яких працюю? Якщо ні, що саме потрібно змінити або переосмислити, щоб він став здійсненним?"},{"id":"choiceSummary","type":"textarea","title":"Підсумкове обґрунтування вибору","help":"Зведіть попередні відповіді в один зв’язний авторський текст. Не копіюйте механічно. Сформулюйте цілісну логіку вибору.","placeholder":"Чому саме ця тема? Чому зараз? Чому вона важлива глядачеві? Чому саме ви хочете її поставити? Чи реально це здійснити?","wide":true,"theory":"Підсумкове обґрунтування - це цілісний текст, у якому поєднуються контекст теми, її актуальність, мистецький потенціал, ваша авторська мотивація та реальні умови майбутньої постановки.\n\nПісля завершення цього тексту ви повинні мати чітку відповідь на п’ять питань: чому саме ця тема; чому саме зараз; чому вона може бути важливою для глядача; чому саме ви хочете створити цей проєкт; чи можете ви реально втілити його у наявних умовах.\n\nЦей текст стане переходом до наступного етапу, точного ідейно-тематичного аналізу."}]};
const PROJECT_PARAMETERS_SECTION={"id":"project-parameters","title":"1.2. Вихідні параметри проєкту","intro":"Цей розділ фіксує вихідні характеристики майбутнього проєкту. Тут важливо коротко і точно визначити, що саме ви створюєте, для кого, де, коли, у якому масштабі та форматі. Теоретичне пояснення до кожного пункту відкривається окремо.","published":true,"blocks":[{"id":"projectTitle","type":"text","title":"1.2.1. Назва проєкту","help":"Назва може бути робочою. Вона має відображати ідею, смисловий напрям або центральний образ проєкту.","placeholder":"Введіть назву проєкту","required":true,"theory":"Назва проєкту - це концентроване словесне вираження його ідеї та змісту. Вона не просто позначає подію, а має спрямовувати сприйняття глядача до головного смислу, авторського задуму або центрального образу.\n\nНа початковому етапі назва може бути робочою. У процесі роботи над проблемою, темою, ідеєю, художнім образом і режисерським задумом вона може уточнюватися або повністю змінюватися.\n\nНазва може бути прямою, образною, метафоричною, символічною або асоціативною. Головне, щоб вона відповідала ідеї проєкту, не була випадковою і могла органічно існувати в афіші, програмі та комунікації з глядачем.\n\nПеревірте себе питанням: чи передає ця назва головний смисловий напрям мого проєкту?"},{"id":"projectForm","type":"text","title":"1.2.2. Форма проєкту","help":"Вкажіть форму без прикметників: концерт, шоу, вистава, вечір, церемонія, конкурс, фестиваль, свято або презентація.","placeholder":"Наприклад: концерт","theory":"Форма проєкту - це тип сценічної або мистецько-видовищної організації майбутньої події. Вона відповідає на базове питання: що саме я створюю?\n\nУ назві форми не використовуйте прикметники, які характеризують художню природу проєкту. Такі уточнення з’являться у жанрі. Наприклад, форма: концерт. Жанрове уточнення: тематичний, ювілейний, гумористичний тощо.\n\nКОНЦЕРТ\nПублічний виступ артистів за визначеною, заздалегідь складеною програмою. Основна особливість концерту - побудова з окремих номерів, кожен із яких має відносну самостійність. Номери поєднуються режисером у цілісну програму.\n\nШОУ\nВидовищна сценічна форма, в основі якої лежать яскраві номери, атракціони та виразне використання технічних можливостей. Для шоу характерні видовищність, динаміка, візуальна виразність і сильний емоційний вплив. Чіткий сюжетний хід не є обов’язковим.\n\nШОУ-ВИСТАВА / ВИСТАВА\nСценічна форма, побудована за законами єдиної дії, історії або сюжету. У шоу-виставі поєднуються принципи театральної вистави та видовищного шоу. Номери, технічні компоненти, сценографія та інші засоби підпорядковуються єдиній дії. Основна відмінність від концерту - обов’язкова сюжетна або чітко розгорнута драматургічна побудова.\n\nВЕЧІР\nОсоблива сценічна форма, у якій поєднуються художні та документальні матеріали. Для вечора характерні реальні герої, документи, спогади, архівні матеріали та жива комунікація з аудиторією. Зазвичай вечір має конкретну присвяту людині, події, даті або мистецькому явищу.\n\nЦЕРЕМОНІЯ\nУрочисте видовищне дійство з ритуально-обрядовою природою. Воно створюється з особливої нагоди: відкриття, закриття, нагородження, вшанування, посвяти тощо. Основна особливість - чіткий порядок символічних і ритуальних дій, які режисер перетворює на художньо осмислену сценічну подію.\n\nКОНКУРС\nПублічне змагання, у якому через виступи, демонстрацію майстерності або творчих досягнень визначають найкращих серед учасників. Обов’язковими є змагальність, правила, критерії оцінювання та результат. Саме невідомість результату створює природну драматургію напруження.\n\nФЕСТИВАЛЬ\nМасове мистецьке або культурне дійство, що об’єднує численних учасників, жанри, події, сцени та аудиторії. Основні риси фестивалю - масштабність і поліжанровість. Окремі події поєднуються спільною темою, ідеєю, образом і загальною режисерською логікою.\n\nСВЯТО\nМасове культурне дійство, приурочене до певної події, дати або теми, яке об’єднує людей спільним переживанням. У межах свята можуть поєднуватися концерти, сценічні виступи, ігрові зони, виставкові та інтерактивні складові. Режисер має об’єднати різні компоненти в одну масштабну подію.\n\nПРЕЗЕНТАЦІЯ\nТеатралізоване публічне дійство, спрямоване на представлення нового продукту, ідеї, твору або проєкту. Основна особливість - наявність конкретного об’єкта презентації, навколо якого будується вся драматургія. Режисер організовує не лише показ, а й момент відкриття, інтригу, емоційне сприйняття та запам’ятовування представленого об’єкта.\n\nПід час вибору форми не намагайтеся зробити назву складнішою. Спочатку точно визначте, до якого типу великої сценічної події належить ваш задум. Художні уточнення ви сформулюєте в пункті «Жанр»."},{"id":"projectGenre","type":"text","title":"1.2.3. Жанр","help":"Уточніть художню природу обраної форми. Саме тут з’являються характеристики, які не слід додавати до назви форми.","placeholder":"Вкажіть жанрову характеристику","theory":"Жанр - це авторське бачення та мистецька конкретизація форми проєкту. Якщо форма відповідає на питання «що саме я створюю?», то жанр уточнює, яким є цей проєкт художньо, в якому емоційному, стильовому та образному ключі він існує.\n\nСаме в жанрі з’являються прикметникові характеристики. Наприклад, форма може бути «концерт», а жанрове визначення уточнює його художню природу: тематичний, ювілейний, гумористичний та інший відповідно до конкретного задуму.\n\nЖанр впливає на характер сценічної дії, спосіб існування виконавців, режисерські прийоми, музику, світло, сценографію, пластичне рішення, монтаж і темпоритм. Усі складові постановки мають існувати в єдиному жанровому ключі.\n\nНе обирайте жанр тільки як красиве слово. Він повинен реально проявлятися у способі, яким ви будете будувати проєкт."},{"id":"projectScale","type":"text","title":"1.2.4. Масштаб проєкту","help":"Визначте масштаб події та рівень її охоплення. За потреби вкажіть орієнтовну кількість учасників і глядачів.","placeholder":"Наприклад: великий, міський","theory":"Масштаб визначає розмір, складність і рівень охоплення майбутнього проєкту. Його доцільно розглядати у двох площинах.\n\nЗа масштабом самої події: камерний, середній, великий, масовий.\n\nЗа рівнем охоплення: локальний, міський, регіональний, національний, міжнародний.\n\nМасштаб залежить не лише від кількості глядачів. На нього впливають кількість виконавців, склад творчо-постановочної групи, кількість майданчиків, технічна складність, тривалість і загальний обсяг постановочного процесу.\n\nЗа потреби зазначте орієнтовну кількість виконавців, інших учасників і глядачів. Коротко поясніть, чому саме так визначаєте масштаб проєкту."},{"id":"projectVenue","type":"text","title":"1.2.5. Простір / майданчик проведення","help":"Вкажіть реальний або передбачуваний майданчик, у якому має відбуватися проєкт.","placeholder":"Назва або тип майданчика, місто, локація","theory":"Простір / майданчик проведення - це конкретне фізичне середовище, у якому має відбуватися проєкт. Це може бути театральна сцена, концертний зал, клубний простір, площа, вулиця, стадіон, парк, музей, павільйон, виробничий або інший нетрадиційний простір.\n\nНа цьому етапі потрібно визначити саме реальний або передбачуваний майданчик. Художнє осмислення простору буде розглядатися пізніше в режисерському задумі.\n\nМайданчик впливає на розміри сценічної дії, розташування глядача, рух виконавців, можливості світла, звуку, відео, декорацій, монтажу, логістики та безпеки. Тому простір потрібно обирати не тільки за зовнішньою привабливістю, а й з огляду на те, чи дозволяє він реально втілити задум.\n\nЯкщо задум створюється спеціально для конкретної локації і суттєво залежить від її архітектури, історії або функції, обов’язково зазначте це."},{"id":"projectFormat","type":"text","title":"1.2.6. Формат проєкту","help":"Вкажіть спосіб існування сценічного проєкту: офлайн, онлайн або гібридний; стаціонарний або мобільний; одномайданчиковий або багатомайданчиковий.","placeholder":"Наприклад: офлайн, стаціонарний, одномайданчиковий","theory":"Формат визначає спосіб існування сценічного проєкту та організації взаємодії з аудиторією. Проєкт може бути офлайн, онлайн або гібридним; стаціонарним або мобільним; одномайданчиковим або багатомайданчиковим.\n\nМи працюємо зі сценічним мистецько-видовищним проєктом. Він не обов’язково відбувається на традиційній сцені, але передбачає організовану подію, дію, виконавців і аудиторію. Суто телевізійний або відеопроєкт у цьому пункті не розглядається.\n\nУ багатомайданчиковому форматі окремі частини можуть відбуватися в різних просторах. У гібридному частина аудиторії може бути фізично присутньою, а частина долучатися дистанційно.\n\nГоловне питання: яким способом глядач буде присутній у події і як буде організоване саме існування проєкту?"},{"id":"projectAudience","type":"textarea","title":"1.2.7. Цільова аудиторія","help":"Коротко визначте, для кого створюється проєкт. Врахуйте не тільки вік, а й інтереси, культурний досвід та мотивацію присутності.","placeholder":"Хто ваш глядач і чому цей проєкт адресований саме йому?","theory":"Цільова аудиторія - це конкретна група людей, для яких створюється проєкт. Визначення аудиторії не повинно обмежуватися лише віком.\n\nПодумайте про соціально-демографічні характеристики, культурний і глядацький досвід, інтереси, мотивацію присутності, очікування від події та можливий спосіб участі. Для одного проєкту глядач залишається спостерігачем, для іншого може активно взаємодіяти з виконавцями або простором.\n\nРежисеру важливо розуміти, хто ці люди, чому вони прийдуть, що вони вже знають про тему, які асоціації та очікування можуть мати і якою може бути їхня емоційна реакція.\n\nЗнання аудиторії надалі впливатиме на мову проєкту, тривалість, темп, способи комунікації, режисерські прийоми і характер взаємодії з глядачем."},{"id":"projectDateTime","type":"text","title":"1.2.8. Дата і час проведення","help":"Якщо точні дата і час ще не визначені, вкажіть орієнтовний період проведення.","placeholder":"Наприклад: 07.11.2026, 19:00 або орієнтовно грудень 2026","theory":"Дата і час проведення - це не лише організаційні дані. Для багатьох великих форм вони впливають і на режисерське рішення.\n\nДата може бути пов’язана зі святом, історичною подією, ювілеєм, фестивальним календарем, сезоном або іншим контекстом. Час проведення впливає на використання природного і сценічного світла, відео, атмосферу, погодні умови, транспортну доступність та тривалість перебування глядача.\n\nОсобливо важливими дата і час є для подій у відкритому просторі. Денне і вечірнє дійство на одному майданчику можуть потребувати принципово різних режисерських і технічних рішень.\n\nЯкщо точні дата та час ще не визначені, зазначте орієнтовний період. Його можна буде уточнити пізніше."},{"id":"projectDuration","type":"text","title":"1.2.9. Орієнтовна тривалість / хронометраж","help":"Вкажіть передбачувану тривалість усього проєкту. Для складних подій можна додати орієнтовну тривалість основних блоків.","placeholder":"Наприклад: 90 хвилин","theory":"Хронометраж - це передбачувана тривалість усього проєкту. Його варто визначити вже на початку, навіть якщо надалі він буде уточнюватися.\n\nТривалість безпосередньо впливає на композицію, архітектоніку, кількість епізодів і номерів, темпоритм, розподіл кульмінацій, переходи між частинами та здатність аудиторії утримувати увагу.\n\nПроєкт тривалістю 45 хвилин і проєкт тривалістю три години не можуть мати однакову драматургічну організацію. Для фестивалю, свята або багатомайданчикового проєкту важливо визначити не лише загальну тривалість, а й приблизний хронометраж окремих блоків або програм.\n\nНа цьому етапі достатньо реалістичної орієнтовної цифри. Пізніше вона буде уточнюватися разом зі сценарієм і постановочним планом."}]};
const RESEARCH_SECTION={"id":"research-materials","title":"1.3. Пошук, дослідження та збір матеріалу","intro":"Після визначення вихідних параметрів проєкту починається дослідницький етап. Ваше завдання не просто накопичити посилання і файли, а зібрати матеріал, який допоможе глибше зрозуміти тему і поступово сформувати режисерський задум. Знайдені факти, документи, тексти, музика, зображення, відео, сценічні приклади та асоціації можуть згодом перетворитися на драматургію, образи, сценарний хід, монтажні зв’язки та інші засоби сценічного вираження. Матеріал доцільно збирати у двох напрямах: документальному та художньому. Паралельно ведіть режисерський блокнот, де фіксуйте власні ідеї, асоціації та можливі способи поєднання знайденого матеріалу.","published":true,"blocks":[{"id":"documentaryMaterials","type":"material_collection","collectionKind":"documentary","title":"1.3.1. Документальний матеріал","help":"Додавайте факти, документи, архівні матеріали, фото, відео, інтерв’ю, спогади, публікації та інші джерела, пов’язані з реальною дійсністю.","theory":"Документальний матеріал пов’язаний із реальною дійсністю і дає режисерові фактичну основу для осмислення теми. Це можуть бути історичні та сучасні факти, архівні документи, листи, щоденники, спогади, інтерв’ю, фотографії, відеозаписи, аудіозаписи, газетні та журнальні публікації, статистика, біографічні відомості, офіційні документи, музейні предмети, артефакти, іконографічні матеріали, матеріали з конкретного місця або середовища.\n\nДокументальний матеріал не слід просто накопичувати. Кожен знайдений факт або документ потрібно осмислювати з позиції майбутньої постановки: що він відкриває в темі, яку суперечність виявляє, який образ або епізод може народити, чи може стати основою тексту, відеофрагмента, сценічної дії або монтажного зіставлення.\n\nРежисер може проводити і власне дослідження: записувати інтерв’ю, фотографувати місце, працювати з архівами, музеями, приватними колекціями, збирати усні історії та свідчення. Відібрані факти і документи надалі можуть бути образно переосмислені і перетворені на факти мистецтва: драматургію, сценарний хід, сценічний образ, персонажа, звук, відео або інший художній засіб.\n\nДо кожного матеріалу обов’язково залишайте режисерську нотатку: як саме його можна використати або з чим його можна поєднати."},{"id":"artisticMaterials","type":"material_collection","collectionKind":"artistic","title":"1.3.2. Художній матеріал","help":"Збирайте твори та фрагменти мистецтва, які можуть стати змістовим, образним, музичним, пластичним або візуальним матеріалом майбутнього проєкту.","theory":"Художній матеріал уже є результатом мистецького осмислення дійсності. До нього належать літературні твори, поезія, драматургія, музика, пісні, кінематограф, фотографія, живопис, хореографія, сценічні номери, вистави, сценографія, костюм, звукові та відеоматеріали, а також інші твори різних видів мистецтва.\n\nСценарний матеріал великого видовищного проєкту може бути художнім, літературним, образотворчим, звуковим і музичним. Джерелом можуть стати як цілі твори, так і окремі фрагменти, образи, мотиви, фактури, ритми, інтонації, принципи побудови або режисерські прийоми.\n\nВажливо не копіювати знайдене рішення, а зрозуміти, що саме в ньому вас цікавить. Це може бути музична тема, спосіб появи виконавця, пластичний принцип, колір, композиція кадру, характер монтажу, сценографічний образ, контраст, ритм або спосіб взаємодії з глядачем.\n\nДо кожного художнього матеріалу фіксуйте, що саме вас зацікавило і як цей матеріал може працювати у вашому проєкті: стати основою епізоду, створити атмосферу, вступити в контраст із документом, підказати образ, просторове рішення або принцип монтажу."},{"id":"directorNotebook","type":"material_collection","collectionKind":"notes","title":"1.3.3. Режисерський блокнот","help":"Фіксуйте ідеї одразу, коли вони виникають. Тут можуть з’являтися образи, монтажні зв’язки, просторові рішення, питання, музичні та візуальні задуми.","theory":"Режисерський блокнот потрібен для того, щоб не втрачати думки, які виникають під час дослідження. Не кожна ідея одразу належить до конкретного документа чи твору. Іноді спочатку з’являється образ, фраза, ритм, спосіб переходу між епізодами, поєднання двох матеріалів або питання, на яке ще немає відповіді.\n\nФіксуйте такі думки одразу. Вони не зобов’язані бути остаточними або правильними. Це робочий простір режисера. Тут можна записати, як поєднати архівний документ із музикою, яким може бути пролог, який предмет може стати образом, де використати тишу, як змінити простір, як підвести глядача до певного переживання.\n\nОсобливо важливо фіксувати зв’язки між матеріалами. Саме в таких зв’язках часто починає народжуватися монтаж, епізод, сценарно-режисерський хід або майбутній художній образ."}]};
function upgradeSchema(raw){const x=JSON.parse(JSON.stringify(raw||DEFAULT_SCHEMA));x.sections=Array.isArray(x.sections)?x.sections:[];x.sections=x.sections.filter(s=>s.id!=="passport"&&s.id!==JUSTIFICATION_SECTION.id&&s.id!==PROJECT_PARAMETERS_SECTION.id&&s.id!==RESEARCH_SECTION.id);x.sections.unshift(JSON.parse(JSON.stringify(RESEARCH_SECTION)));x.sections.unshift(JSON.parse(JSON.stringify(PROJECT_PARAMETERS_SECTION)));x.sections.unshift(JSON.parse(JSON.stringify(JUSTIFICATION_SECTION)));x.contentVersion=Math.max(4,Number(x.contentVersion||0));return x}
const DEFAULT_SCHEMA={version:1,title:"Режисерська лабораторія",subtitle:"Індивідуальна траєкторія розробки режисерського проєкту",sections:[
{id:"passport",title:"1. Паспорт проєкту",intro:"Це стартова картка майбутнього проєкту. Визнач робочу назву, форму та коротко сформулюй задум.",published:true,blocks:[{id:"projectTitle",type:"text",title:"Робоча назва проєкту",help:"Назва може бути робочою і змінюватися в процесі.",placeholder:"Введи робочу назву",required:true},{id:"format",type:"text",title:"Форма / жанр",help:"Визнач сценічну форму або жанрову природу задуму.",placeholder:"Наприклад: музично-сценічний перформанс"},{id:"concept",type:"textarea",title:"Коротка концепція",help:"Стисло опиши, що саме ти хочеш створити і чому цей задум важливий.",placeholder:"2–5 абзаців"}]},
{id:"dramaturgy",title:"2. Драматургічна основа",intro:"У цьому розділі формується смислова й драматургічна основа майбутнього проєкту.",published:true,blocks:[{id:"theme",type:"textarea",title:"Тема",help:"Сформулюй предмет художнього осмислення."},{id:"idea",type:"textarea",title:"Ідея",help:"Сформулюй основну авторську думку."},{id:"problem",type:"textarea",title:"Проблематика",help:"Які питання та суперечності досліджує проєкт?"},{id:"conflict",type:"textarea",title:"Конфлікт",help:"Опиши головне зіткнення сил, позицій або цінностей."},{id:"structure",type:"textarea",title:"Архітектоніка / структура",help:"Опиши великі частини або логіку розвитку дії."}]},
{id:"director",title:"3. Режисерський задум",intro:"Розділ переводить драматургічну основу у мову режисури.",published:true,blocks:[{id:"directorConcept",type:"textarea",title:"Режисерський задум"},{id:"image",type:"textarea",title:"Образ проєкту"},{id:"techniques",type:"textarea",title:"Режисерські прийоми та засоби виразності"}]},
{id:"staging",title:"4. Постановочне рішення",intro:"Тут задум конкретизується через простір, мізансцену, сценографію, світло, звук, відео та темпоритм.",published:true,blocks:[{id:"space",type:"textarea",title:"Простір і мізансценування"},{id:"visual",type:"textarea",title:"Сценографія / візуальне рішення"},{id:"tech",type:"textarea",title:"Світло, звук, відео"},{id:"rhythm",type:"textarea",title:"Темпоритм"}]},
{id:"plan",title:"5. Режисерсько-постановочний план",intro:"Фінальний робочий розділ збирає матеріал у постановочну документацію.",published:true,blocks:[{id:"plan",type:"textarea",title:"Постановочний план / послідовність епізодів"},{id:"links",type:"link",title:"Робочі посилання",help:"Сценарій, Canva, відео, референси або інші матеріали."}]}
]};
const esc=s=>String(s??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const nl=s=>esc(s).replace(/\n/g,"<br>");
let work=null,feedback={},schema=null,photo="",rendering=false;
function fail(title,text){appEl.innerHTML=`<div class="error-card"><b>${esc(title)}</b><p>${esc(text)}</p></div>`}
if(!cfg){fail("Firebase не налаштовано","Звернися до викладача.");throw new Error("No Firebase config")}
if(!key){fail("Персональне посилання відсутнє","Відкрий посилання, яке надіслав викладач.");throw new Error("No key")}
const fbApp=getApps().length?getApps()[0]:initializeApp(cfg);
const db=getFirestore(fbApp),storage=getStorage(fbApp);
const workRef=doc(db,"rems_directing_lab_work",key),feedbackRef=doc(db,"rems_directing_lab_feedback",key),schemaRef=doc(db,"rems_directing_lab_schema","current");
const sectionState=id=>work?.sectionStates?.[id]||work?.stages?.[id]||{};
const sectionFeedback=id=>feedback?.sections?.[id]||feedback?.stages?.[id]||{};
const answerFor=(section,block)=>{const a=work?.answers?.[block.id];if(a!==undefined)return a;const old=work?.stages?.[section.id]?.[block.id];return old!==undefined?{value:old}:{}};
function publishedSections(){return(schema?.sections||[]).filter(s=>s.published!==false)}
function progress(){const blocks=publishedSections().flatMap(s=>(s.blocks||[]).filter(b=>b.type!=="theory"));let filled=0;for(const b of blocks){const s=publishedSections().find(x=>(x.blocks||[]).some(y=>y.id===b.id));const a=answerFor(s,b)||{};if(b.type==='table'&&Array.isArray(a.rows)&&a.rows.some(r=>r.some(v=>String(v||'').trim())))filled++;else if(b.type==='file'&&Array.isArray(a.files)&&a.files.length)filled++;else if(b.type==='material_collection'&&Array.isArray(a.items)&&a.items.length)filled++;else if(b.type==='checklist'&&Array.isArray(a.values)&&a.values.length)filled++;else if(String(a.value||'').trim())filled++}return{total:blocks.length,filled,pct:blocks.length?Math.round(filled/blocks.length*100):0}}
function materialTypeOptions(kind){
 const map={documentary:["Документ","Архівний матеріал","Фото","Відео","Аудіо","Інтерв’ю","Стаття / публікація","Статистика","Біографічний матеріал","Лист / щоденник / спогад","Артефакт","Інше"],artistic:["Література","Поезія","Драматургія","Музика","Пісня","Кінематограф","Сценічний номер","Вистава","Хореографія","Живопис","Фотографія","Сценографія","Костюм","Відеоматеріал","Звуковий матеріал","Інше"],notes:["Ідея","Образ / метафора","Монтажний зв’язок","Просторове рішення","Музична ідея","Візуальна ідея","Питання","Інше"]};return map[kind]||map.documentary
}
function materialStatusOptions(v){return[["found","Знайдено"],["study","Вивчаю"],["selected","Відібрано для проєкту"],["maybe","Можливо використаю"],["rejected","Відмовився"]].map(([k,t])=>`<option value="${k}" ${v===k?'selected':''}>${t}</option>`).join('')}
function materialItemHtml(block,item={},disabled=''){
 const kind=block.collectionKind||'documentary',id=String(item.id||crypto.randomUUID?.()||`${Date.now()}-${Math.random()}`),types=materialTypeOptions(kind);
 const files=Array.isArray(item.files)?item.files:[];
 if(kind==='notes')return `<article class="material-item" data-material-item="${esc(id)}" data-block-id="${esc(block.id)}"><div class="material-item-top"><select data-mi="type" ${disabled}>${types.map(t=>`<option ${item.type===t?'selected':''}>${esc(t)}</option>`).join('')}</select><label class="material-important"><input type="checkbox" data-mi="important" ${item.important?'checked':''} ${disabled}> ★ Важливе</label><button class="material-remove" type="button" data-remove-material ${disabled}>×</button></div><input data-mi="title" ${disabled} value="${esc(item.title||'')}" placeholder="Коротка назва нотатки"><textarea data-mi="directorNote" ${disabled} rows="4" placeholder="Запишіть ідею, асоціацію, зв’язок між матеріалами або питання…">${esc(item.directorNote||'')}</textarea><div class="material-link-row"><input data-mi="link" ${disabled} value="${esc(item.link||'')}" placeholder="Посилання, якщо є"><label class="material-upload ${!work.driveUrl?'is-disabled':''}"><input type="file" data-material-file="${esc(block.id)}" data-material-item-id="${esc(id)}" ${disabled}><span>＋ Файл</span></label></div><div class="material-files">${files.map(f=>`<a href="${esc(f.url||'#')}" target="_blank" rel="noopener">📎 ${esc(f.name||'Файл')}</a>`).join('')}</div><div class="upload-note" data-upload-note="${esc(block.id)}:${esc(id)}"></div></article>`;
 return `<article class="material-item" data-material-item="${esc(id)}" data-block-id="${esc(block.id)}"><div class="material-item-top"><select data-mi="type" ${disabled}>${types.map(t=>`<option ${item.type===t?'selected':''}>${esc(t)}</option>`).join('')}</select><select data-mi="status" ${disabled}>${materialStatusOptions(item.status||'found')}</select><label class="material-important"><input type="checkbox" data-mi="important" ${item.important?'checked':''} ${disabled}> ★ Важливе</label><button class="material-remove" type="button" data-remove-material ${disabled}>×</button></div><div class="material-two"><input data-mi="title" ${disabled} value="${esc(item.title||'')}" placeholder="Назва матеріалу"><input data-mi="author" ${disabled} value="${esc(item.author||'')}" placeholder="Автор / герой / виконавець"></div><div class="material-two"><input data-mi="source" ${disabled} value="${esc(item.source||'')}" placeholder="Джерело"><input data-mi="timecode" ${disabled} value="${esc(item.timecode||'')}" placeholder="Фрагмент / сторінка / таймкод"></div><textarea data-mi="description" ${disabled} rows="3" placeholder="Що тут важливого? Що саме ви знайшли або що вас зацікавило?">${esc(item.description||'')}</textarea><textarea class="director-note" data-mi="directorNote" ${disabled} rows="4" placeholder="Режисерська нотатка: як це можна використати, з чим поєднати, який образ, епізод або прийом це може підказати?">${esc(item.directorNote||'')}</textarea><div class="material-link-row"><input data-mi="link" ${disabled} value="${esc(item.link||'')}" placeholder="Посилання на джерело"><label class="material-upload ${!work.driveUrl?'is-disabled':''}"><input type="file" data-material-file="${esc(block.id)}" data-material-item-id="${esc(id)}" ${disabled}><span>＋ Додати файл</span></label></div><div class="material-files">${files.map(f=>`<a href="${esc(f.url||'#')}" target="_blank" rel="noopener">📎 ${esc(f.name||'Файл')}</a>`).join('')}</div><div class="upload-note" data-upload-note="${esc(block.id)}:${esc(id)}"></div></article>`
}
function materialCollectionHtml(section,block,a,state){const disabled=state==='approved'?'disabled':'',items=Array.isArray(a.items)?a.items:[];return `<div class="material-collection" data-material-collection="${esc(block.id)}">${items.map(x=>materialItemHtml(block,x,disabled)).join('')||'<div class="material-empty">Ще нічого не додано. Почніть із першого матеріалу або нотатки.</div>'}${state==='approved'?'':`<button class="material-add" type="button" data-add-material="${esc(block.id)}">＋ ${block.collectionKind==='notes'?'Додати нотатку':'Додати матеріал'}</button>`}</div>`}
