 if(block.type==='text'||block.type==='link')return`<div class="work-block${wide}">${head}${help}${sample}<input data-answer="${esc(block.id)}" data-type="${esc(block.type)}" ${disabled} value="${esc(a.value||'')}" placeholder="${esc(block.placeholder||'')}"></div>`;
 if(block.type==='textarea')return`<div class="work-block${wide}">${head}${help}${sample}<textarea data-answer="${esc(block.id)}" data-type="textarea" ${disabled} placeholder="${esc(block.placeholder||'')}" rows="6">${esc(a.value||'')}</textarea></div>`;
