 if(block.type==='table'){const cols=(block.columns||[]).length?block.columns:["Колонка 1","Колонка 2"];const rows=Array.isArray(a.rows)&&a.rows.length?a.rows:[Array(cols.length).fill("")];return`<div class="work-block wide-block">${head}${help}${sample}<div class="table-shell"><table data-table="${esc(block.id)}"><thead><tr>${cols.map(c=>`<th>${esc(c)}</th>`).join('')}</tr></thead><tbody>${rows.map((r,ri)=>`<tr>${cols.map((c,ci)=>`<td><textarea data-cell="${ri}:${ci}" ${disabled}>${esc(r[ci]||'')}</textarea></td>`).join('')}</tr>`).join('')}</tbody></table></div>${state==='approved'?'':`<button class="inline-btn" type="button" data-add-row="${esc(block.id)}">＋ Додати рядок</button>`}</div>`}
