function collectSection(sectionId){const section=schema.sections.find(s=>s.id===sectionId),box=appEl.querySelector(`[data-section="${CSS.escape(sectionId)}"]`),answers={};for(const block of(section.blocks||[])){if(block.type==='theory')continue;if(block.type==='material_collection'){answers[block.id]={items:collectMaterialItems(box,block.id)}}else if(block.type==='checklist'){answers[block.id]={values:[...box.querySelectorAll(`[data-check="${CSS.escape(block.id)}"]:checked`)].map(x=>x.value)}}else if(block.type==='table'){const t=box.querySelector(`[data-table="${CSS.escape(block.id)}"]`),rows=[];t?.querySelectorAll('tbody tr').forEach(tr=>rows.push([...tr.querySelectorAll('textarea')].map(x=>x.value.trim())));answers[block.id]={rows}}else if(block.type==='file'){answers[block.id]=answerFor(section,block)||{files:[]}}else{const el=box.querySelector(`[data-answer="${CSS.escape(block.id)}"]`);answers[block.id]={value:el?.value.trim()||''}}}return answers}
