async function downloadWord(){const blob=await buildTextDocx();const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`${safeFileName(work.name)}_Режисерська_лабораторія.docx`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1500)}
async function exportAll(){const zip=new JSZip(),links=[],files=[];const wordBlob=await buildTextDocx();zip.file('01_Текстові_матеріали.docx',wordBlob);for(const section of publishedSections()){for(const block of(section.blocks||[])){const a=answerFor(section,block)||{};if(block.type==='table'){const cols=block.columns||[],rows=a.rows||[];const csv='\uFEFF'+[cols,...rows].map(r=>r.map(v=>`"${String(v||'').replace(/"/g,'""')}"`).join(';')).join('\r\n');zip.file(`02_Таблиці/${safeFileName(section.title)}_${safeFileName(block.title)}.csv`,csv)}else if(block.type==='file'){for(const f of(a.files||[]))files.push(`${section.title} — ${block.title}: ${f.name} — ${f.url}`)}else if(block.type==='link'){const v=String(a.value||'').trim();if(v)links.push(`${block.title}: ${v}`)}}}zip.file('03_Посилання.txt',links.join('\n'));zip.file('04_Прикріплені_файли.txt',files.join('\n'));const blob=await zip.generateAsync({type:'blob'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`${safeFileName(work.name)}_режисерська_лабораторія.zip`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1500)}
function openTheoryModal(btn){const modal=appEl.querySelector('#theoryModal');if(!modal)return;appEl.querySelector('#theoryModalTitle').textContent=btn.dataset.theoryTitle||'Теоретичний матеріал';appEl.querySelector('#theoryModalCopy').innerHTML=nl(btn.dataset.theory||'');modal.classList.add('open');modal.setAttribute('aria-hidden','false');document.body.classList.add('modal-open')}function closeTheoryModal(){const modal=appEl.querySelector('#theoryModal');if(!modal)return;modal.classList.remove('open');modal.setAttribute('aria-hidden','true');document.body.classList.remove('modal-open')}
function bind(){appEl.querySelectorAll('[data-theory]').forEach(b=>b.onclick=()=>openTheoryModal(b));appEl.querySelectorAll('[data-add-material]').forEach(b=>b.onclick=()=>{const blockId=b.dataset.addMaterial,section=schema.sections.find(s=>(s.blocks||[]).some(x=>x.id===blockId)),block=section?.blocks?.find(x=>x.id===blockId),wrap=appEl.querySelector(`[data-material-collection="${CSS.escape(blockId)}"]`);wrap?.querySelector('.material-empty')?.remove();if(wrap&&block){const tmp=document.createElement('div');tmp.innerHTML=materialItemHtml(block,{id:crypto.randomUUID?.()||String(Date.now()),status:'found'});const card=tmp.firstElementChild;wrap.insertBefore(card,b);card.querySelector('[data-remove-material]')?.addEventListener('click',()=>card.remove());const inp=card.querySelector('[data-material-file]');if(inp)inp.onchange=async()=>{const f=inp.files?.[0];inp.value='';await uploadMaterialFile(inp.dataset.materialFile,inp.dataset.materialItemId,f)}}});appEl.querySelectorAll('[data-remove-material]').forEach(b=>b.onclick=()=>b.closest('[data-material-item]')?.remove());appEl.querySelectorAll('[data-material-file]').forEach(inp=>inp.onchange=async()=>{const f=inp.files?.[0];inp.value='';await uploadMaterialFile(inp.dataset.materialFile,inp.dataset.materialItemId,f)});appEl.querySelector('#backTop')?.addEventListener('click',()=>window.scrollTo({top:0,behavior:'smooth'}));appEl.querySelectorAll('[data-close-theory]').forEach(b=>b.onclick=closeTheoryModal);document.onkeydown=e=>{if(e.key==='Escape')closeTheoryModal()};appEl.querySelectorAll('[data-save]').forEach(b=>b.onclick=async()=>{b.disabled=true;await saveSection(b.dataset.save,false);setTimeout(()=>b.disabled=false,300)});appEl.querySelectorAll('[data-submit]').forEach(b=>b.onclick=async()=>{if(!confirm('Подати цей розділ викладачу на перевірку?'))return;b.disabled=true;await saveSection(b.dataset.submit,true);setTimeout(()=>b.disabled=false,300)});appEl.querySelectorAll('[data-add-row]').forEach(b=>b.onclick=()=>addTableRow(b.dataset.addRow));appEl.querySelectorAll('[data-file]').forEach(inp=>inp.onchange=async()=>{const f=inp.files?.[0];inp.value='';await uploadFile(inp.dataset.file,f)});appEl.querySelector('#exportWord')?.addEventListener('click',downloadWord);appEl.querySelector('#exportLab')?.addEventListener('click',exportAll)}
async function loadSchema(){try{const s=await getDoc(schemaRef);schema=upgradeSchema(s.exists()?s.data():DEFAULT_SCHEMA)}catch(e){console.error(e);schema=upgradeSchema(DEFAULT_SCHEMA)}}
function normalizePhotoSrc(v){const x=String(v||'').trim();if(!x)return'';if(/^data:|^blob:|^https?:\/\//i.test(x))return x;if(x.startsWith('images/'))return `https://rems-44.github.io/REMS-44/${encodeURI(x)}`;return x}
async function loadPhoto(){photo='';try{
 const candidates=[];if(work?.mediaId)candidates.push(String(work.mediaId));
 for(const id of candidates){const s=await getDoc(doc(db,'rems_student_media',id));if(s.exists()){photo=normalizePhotoSrc(s.data()?.photoData||s.data()?.photoUrl);if(photo)return}}
 if(work?.studentId){const qs=await getDocs(query(collection(db,'rems_student_media'),where('studentId','==',String(work.studentId)),limit(1)));if(!qs.empty){photo=normalizePhotoSrc(qs.docs[0].data()?.photoData||qs.docs[0].data()?.photoUrl);if(photo)return}}
 if(work?.mediaId){const ps=await getDoc(doc(db,'rems_public_profiles',String(work.mediaId)));if(ps.exists()){photo=normalizePhotoSrc(ps.data()?.photo||ps.data()?.photoData);if(photo)return}}
 photo=normalizePhotoSrc(work?.photoUrl||'');
 }catch(e){console.error('Photo',e)}}
await loadSchema();
onSnapshot(workRef,async snap=>{if(!snap.exists()){fail('Лабораторію ще не активовано','Попроси викладача активувати персональний доступ у REMS-Control.');return}work=snap.data()||{};await loadPhoto();render()},err=>{console.error(err);fail('Не вдалося відкрити лабораторію','Перевір посилання та інтернет-з’єднання.')});
onSnapshot(feedbackRef,snap=>{feedback=snap.exists()?snap.data()||{}:{};if(work)render()},err=>{console.error('Feedback:',err);feedback={};if(work)render()});
